function completeObjective(reason='Objectif accompli'){if(state.objectiveDone)return;state.objectiveDone=true;const b=beat();state.completedBeats.add(chapter().id+':'+b.id);state.stats.beats=state.completedBeats.size;if(!String(b.mode).startsWith('scripted')&&state.stats.damageTaken===state.beatDamageStart)state.stats.perfectBeats=(state.stats.perfectBeats||0)+1;for(const f of b.flags||[])state.flags[f]=true;if((b.flags||[]).includes('scar_blooded')){state.blooded=true;state.maskOn=false;state.flags.scar_unmasked=true;}if((b.flags||[]).includes('scar_implanted_hidden'))state.infectedHidden=true;if((b.flags||[]).includes('plasma_recovered'))state.plasma=true;if((b.flags||[]).includes('lex_gear'))state.lexGear=true;if((b.flags||[]).includes('scar_fatal'))state.fatal=true;if((b.flags||[]).includes('celtic_blades_melt')){state.disabledWeapons['Celtic:wrist_blades']=true;if(state.actor==='Celtic'&&state.weapon==='wrist_blades')state.weapon='combistick'}status(reason);sfx('objective');const isLastBeat=state.beatIndex>=chapter().beats.length-1;const after=()=>{if(isLastBeat){state.unlockedChapter=Math.max(state.unlockedChapter,Math.min(CAMPAIGN.chapters.length-1,state.chapterIndex+1));if(chapter().next)loadChapter(state.chapterIndex+1,0,true);else{state.flags.campaign_complete=true;save(true);ui.menu.classList.add('show')}}else loadBeat(state.beatIndex+1,true);save(true)};cinematic(chapter().title,cinematicTextFor(b),[state.actor,b.mode,'CONTINUITÉ ÉCRAN'],after)}
function nearestEnemy(maxRange=9999){let best=null,d=Infinity;for(const e of state.enemies){if(e.dead||e.lane!==state.lane)continue;const dd=Math.abs(e.x-state.x);if(dd<d&&dd<=maxRange){best=e;d=dd}}return best}
function acidSplash(e,w){if(!e.acid)return;if(w?.acidRisk&&Math.abs(e.x-state.x)<120){damagePlayer(6,'Éclaboussure acide');state.armor=Math.max(0,state.armor-12);state.stats.acidHits++;state.flags.acid_contact=true;status('ACIDE // ARME ET ARMURE TOUCHÉES')}}
function killEnemy(e,w){e.dead=true;state.stats.kills++;acidSplash(e,w);burst(e.x,laneY[e.lane]-38,e.acid?'acid':'sparks');sfx(e.acid?'acid':'hit');checkCombatComplete()}
function damageEnemy(e,dmg,w){if(e.dead)return;if(e.type==='weyland'&&!e.hostile){state.honor=Math.max(0,state.honor-5);state.stats.invalidAttempts++;status('CODE DE CHASSE // WEYLAND N’EST PAS ENCORE UNE CIBLE VALIDE');sfx('error');updateHUD();return}const flags=beat().flags||[];if(beat().mode==='duel_quinn'&&e.type==='quinn'){if(w?.kind!=='melee'){status('CELTIC // DUEL RAPPROCHÉ REQUIS');return}state.combatHits++;e.hp=Math.max(20,e.hp-dmg*.35);if(state.combatHits>=3)completeObjective('Quinn est dominé au bord du puits.');return}if(beat().mode==='quinn_finish'&&e.type==='quinn_injured'){if(w?.kind!=='melee'){status('SCAR // EXÉCUTION RAPPROCHÉE REQUISE');return}completeObjective('Quinn est achevé au fond du puits.');return}if(beat().mode==='stafford_net'&&e.type==='stafford'){if(w?.kind!=='net'){status('CELTIC // NETGUN REQUIS SUR STAFFORD');return}e.entangled=99;completeObjective('Stafford est immobilisé contre le pilier.');return}if(beat().mode==='stafford_execute'&&e.type==='stafford_trapped'){if(state.weapon!=='combistick'){status('CELTIC // COMBISTICK REQUIS POUR L’EXÉCUTION');return}completeObjective('Stafford est exécuté au combistick.');return}if(e.type==='grid'&&beat().mode==='boss_grid'){
  if(flags.includes('grid_clash')){if(w?.kind!=='melee'){status('CELTIC // CORPS-À-CORPS REQUIS');return}state.combatHits++;e.hp=Math.max(190,e.hp-dmg*.2);if(state.combatHits>=2)completeObjective('Premier choc reproduit.');return}
  if(flags.includes('grid_tail_cut')){if(state.weapon!=='wrist_blades'){status('CELTIC // WRIST BLADES REQUISES POUR SECTIONNER LA QUEUE');return}state.combatHits++;e.hp=Math.max(180,e.hp-dmg*.15);if(state.combatHits>=1){burst(e.x,laneY[e.lane]-40,'acid');completeObjective('Queue sectionnée; l’acide détruit les wrist blades.')}return}
  if(flags.includes('grid_grapple')){if(w?.kind!=='melee'||w?.kind==='net'){status('CELTIC // REPRENEZ LE CORPS-À-CORPS');return}state.combatHits++;if(state.combatHits>=3)completeObjective('Grid est projeté contre la pierre.');return}
  if(flags.includes('grid_net_phase')){if(w?.kind!=='net'){status('CELTIC // LE RAZOR NET DOIT ÊTRE UTILISÉ MAINTENANT');return}e.entangled=4.4;state.flags.grid_netted=true;completeObjective('Grid est pris dans le filet.');return}
 }
 if(beat().mode==='ally_lex_kill'&&e.type==='xeno'){e.hp=Math.max(18,e.hp-dmg*.45);state.combatHits++;if(e.hp<=28||state.combatHits>=3){e.hp=18;status('LEX // OUVERTURE AU COMBISTICK');}return}
 if(e.type==='queen'&&beat().mode==='boss_queen_weapon'){const req=beat().requiredWeapon;if(state.weapon!==req){status('REINE // ARME REQUISE : '+(WEAPONS[req]?.name||req).toUpperCase());return}state.queenHits++;e.hp=Math.max(220,e.hp-dmg*.2);if(state.queenHits>=1)completeObjective('Action d’arsenal reproduite contre la Reine.');return}
 if(e.type==='queen'&&beat().mode==='boss_queen'){state.queenHits++;e.hp=Math.max(170,e.hp-dmg*.32);const need=flags.includes('queen_counter')?4:5;if(state.queenHits>=need)completeObjective(flags.includes('queen_counter')?'La Reine est repoussée vers le réservoir.':'Première phase du combat franchie.');return}
 e.hp-=dmg;if(e.hp<=0)killEnemy(e,w)}
function attack(){if(state.cinematic||state.paused||state.fatal)return;ensureWeapon();const w=WEAPONS[state.weapon];if(!w||w.kind==='ceremonial'){status('AUCUNE ATTAQUE DISPONIBLE');return}if(w.energy&&state.energy<w.energy){status('ÉNERGIE INSUFFISANTE');return}if(Number.isFinite(state.weaponAmmo[state.weapon])&&state.weaponAmmo[state.weapon]<=0){status('MUNITIONS ÉPUISÉES POUR CETTE SCÈNE');return}const target=nearestEnemy(w.range);if(!target){status('AUCUNE CIBLE DANS L’AXE');return}if(w.energy)state.energy-=w.energy;if(Number.isFinite(state.weaponAmmo[state.weapon]))state.weaponAmmo[state.weapon]--;if(w.kind==='melee')state.stats.melee++;else state.stats.shots++;if(w.kind==='net')state.shots.push({x:state.x+18,y:laneY[state.lane]-64,vx:13,life:36,type:'net'});else if(w.kind==='projectile')state.shots.push({x:state.x+18,y:laneY[state.lane]-70,vx:16,life:46,type:state.weapon});damageEnemy(target,w.damage,w);state.cameraShake=Math.max(state.cameraShake,w.kind==='melee'?2:1);sfx(w.kind==='melee'?'blade':'shot');updateHUD()}
function checkCombatComplete(){const b=beat();if(['combat_human','combat_xeno','combat_plasma','combat_weyland'].includes(b.mode)&&state.enemies.length&&state.enemies.every(e=>e.dead))completeObjective('Toutes les cibles prévues sont neutralisées.');if(b.mode==='combat_weyland'&&state.enemies.length&&state.enemies.every(e=>e.dead))completeObjective('Weyland a attaqué Scar; la riposte respecte la continuité du film.')}
function damagePlayer(amount,reason){if(state.fatal||state.invuln>0)return;amount*=difficultyMult();state.hp=Math.max(0,state.hp-amount);state.stats.damageTaken+=amount;state.cameraShake=Math.max(state.cameraShake,7);sfx('hurt');if(state.hp<=0)cinematic('ÉCHEC DU RITE',reason+' — reprise au dernier checkpoint.',['CHECKPOINT'],()=>{loadBeat(state.beatIndex,true)})}
function burst(x,y,type){for(let i=0;i<16;i++)state.particles.push({x,y,vx:(Math.random()-.5)*6,vy:(Math.random()-.5)*5,life:50,type})}
function interact(){if(state.cinematic||state.paused)return;const sec=nearestSecondary();if(sec){scanSecondary(sec);return}const b=beat(),nearMarker=Math.abs(state.x-1040)<190;if(b.mode==='weyland_scan'){const w=state.enemies[0];if(w&&!w.hostile&&Math.abs(w.x-state.x)<260){state.flags.weyland_scanned=true;completeObjective('Signature faible confirmée : cible refusée.')}else status('APPROCHEZ WEYLAND POUR LE SCANNER');return}if(b.mode==='honor_weyland'){const w=state.enemies[0];if(w&&!w.hostile&&Math.abs(w.x-state.x)<230){w.hostile=true;status('WEYLAND ATTAQUE // CIBLE DÉSORMAIS VALIDE');sfx('alert');return}if(w?.dead)completeObjective();return}if(b.mode==='boss_queen_chain'){const q=state.enemies[0];if(nearMarker&&q&&Math.abs(q.x-state.x)<220){state.queenChain=true;completeObjective('La chaîne de la Reine est fixée au réservoir.')}else status('ATTIREZ LA REINE PRÈS DU RÉSERVOIR PUIS INTERAGISSEZ');return}if(b.mode==='trophy_cut'&&nearMarker){if(state.weapon!=='dagger'){status('SCAR // CEREMONIAL DAGGER REQUIS');return}completeObjective('Prélèvement accompli au ceremonial dagger.');return}if(['interact','blooding','receive_plasma','craft','self_destruct','mark_lex','elder_gift','ending_predalien','scripted_kill','wrist_scan'].includes(b.mode)&&nearMarker){if(b.mode==='receive_plasma')state.plasma=true;if(b.mode==='blooding')state.blooded=true;if(b.mode==='craft')state.lexGear=true;if(b.mode==='self_destruct'){state.escapeActive=true;state.escapeRemaining=88}if(b.mode==='ending_predalien')state.infectedHidden=false;completeObjective();return}status('AUCUNE INTERACTION À PORTÉE')}
function dodge(){if(state.cinematic||state.paused||state.fatal||state.dodgeCd>0||state.energy<12)return;state.energy-=12;state.dodgeCd=.65;state.invuln=.28;state.stats.dodges++;const dir=keys.left?-1:1;state.x=Math.max(55,Math.min(1200,state.x+dir*125));status('ESQUIVE YAUTJA');sfx('dash')}

function allyKill(e,reason='LEX // CIBLE NEUTRALISÉE'){if(!e||e.dead)return;e.dead=true;state.stats.allyKills=(state.stats.allyKills||0)+1;burst(e.x,laneY[e.lane]-38,e.acid?'acid':'sparks');status(reason);sfx('hit');if(beat().mode==='ally_lex_kill')completeObjective('Lex porte elle-même le coup final au combistick.');if(beat().mode==='ally_rescue')completeObjective('Lex abat l’Alien et protège Scar.');else checkCombatComplete()}
function updateAlly(dt){if(!state.allyActive)return;state.allyLane=state.lane;const desired=Math.max(70,state.x-78);state.allyX+=(desired-state.allyX)*Math.min(1,dt*5.5);state.allyCd=Math.max(0,state.allyCd-dt);const e=nearestEnemy(260);if(!e||e.dead||e.lane!==state.allyLane)return;if(e.type==='queen'){if(state.allyCd<=0){e.hp=Math.max(170,e.hp-5);state.allyCd=1.5}return}if(!['xeno','facehugger'].includes(e.type))return;if(state.allyCd<=0){const dmg=state.lexGear?22:14;e.hp-=dmg;state.allyCd=state.lexGear?.75:1.15;if(e.hp<=0||beat().mode==='ally_rescue'||(beat().mode==='ally_lex_kill'&&e.hp<=28))allyKill(e,beat().mode==='ally_rescue'?'LEX // SAUVETAGE DE SCAR':'LEX // COMBISTICK')} }

function updateAI(dt){for(const e of state.enemies){if(e.dead)continue;if(e.entangled>0){e.entangled=Math.max(0,e.entangled-dt);continue}if(!e.hostile)continue;const base=ENCOUNTERS[e.type]||ENCOUNTERS.xeno;let dist=state.x-e.x,abs=Math.abs(dist);e.laneCd-=dt;e.leapCd-=dt;e.feintCd-=dt;e.chargeCd-=dt;if(e.chargeWindup>0)e.chargeWindup=Math.max(0,e.chargeWindup-dt);if(e.laneSwitch&&e.lane!==state.lane&&e.laneCd<=0&&abs<430){e.lane+=Math.sign(state.lane-e.lane);e.lane=Math.max(0,Math.min((room().lanes||3)-1,e.lane));e.laneCd=base.laneCooldown||2;continue}const xenoVision=['xeno','grid','queen','facehugger'].includes(e.type),detects=xenoVision||!state.cloak||(abs<120&&Math.random()<e.cloakDetect*dt*4);if(!detects)continue;
if(e.type==='grid'&&e.lane===state.lane&&abs<260&&e.feintCd<=0&&(room().lanes||3)>1){e.lane=(e.lane+(Math.random()<.5?1:(room().lanes||3)-1))%(room().lanes||3);e.feintCd=1.1;e.laneCd=.45;status('GRID // CHANGEMENT DE PLAN');continue}
if(e.type==='facehugger'&&e.lane===state.lane&&abs>85&&abs<250&&e.leapCd<=0){e.x+=Math.sign(dist)*Math.min(150,abs-45);e.leapCd=1.25;if(Math.abs(state.x-e.x)<72)damagePlayer(e.damage*1.15,'Bond du Facehugger');continue}
if(e.type==='queen'&&e.lane===state.lane&&abs>170&&abs<430&&e.chargeCd<=0&&e.chargeWindup<=0){e.chargeWindup=.42;e.chargeCd=2.2;status('REINE // CHARGE IMMINENTE');continue}
if(e.type==='queen'&&e.chargeWindup>0){if(e.chargeWindup<.12)e.x+=Math.sign(dist)*e.speed*4.8*dt;continue}
if(base.ranged){if(e.lane!==state.lane)continue;if(abs>165&&abs<(base.attackRange||520)){e.shootCd-=dt;if(e.shootCd<=0){const dmg=e.type==='weyland_hostile'?8:5;damagePlayer(dmg,e.type==='weyland_hostile'?'Jet incendiaire de Weyland':'Tir de sécurité');e.shootCd=base.attackCooldown||1.6}}else if(abs<145)e.x-=Math.sign(dist)*24*dt}else{if(e.lane!==state.lane)continue;const charge=e.type==='queen'&&abs>230?1.55:1,sp=e.speed*charge;if(abs>e.attackRange)e.x+=Math.sign(dist)*sp*dt;if(abs<=e.attackRange){e.attackCd-=dt;if(e.attackCd<=0){damagePlayer(e.damage,e.label+' touche le chasseur');e.attackCd=e.attackCooldown}}}e.x=Math.max(70,Math.min(1160,e.x))}}
function handleMode(dt){const b=beat();if(['reach','stealth','stealth_xeno','escape','escape_sled','escape_start'].includes(b.mode)&&state.x>1105)completeObjective();if(['scripted_stafford','scripted_chopper','scripted_death','scripted_facehugger','scripted_observe','scripted_push'].includes(b.mode)&&state.x>930)completeObjective();if(b.mode==='scripted_wound'&&state.x>720)completeObjective();if(b.mode==='scripted_fatal'&&state.x>720){state.fatal=true;completeObjective()}if(b.mode==='survive'){state.surviveRemaining=Math.max(0,state.surviveRemaining-dt);if(state.surviveRemaining<=0)completeObjective('Le signal de la Reine interrompt l’assaut.')}}
function update(dt,t){if(state.cinematic||state.paused)return;state.dodgeCd=Math.max(0,state.dodgeCd-dt);state.invuln=Math.max(0,state.invuln-dt);const speed=state.fatal?30:(state.cloak?120:190);if(keys.left)state.x-=speed*dt;if(keys.right)state.x+=speed*dt;state.x=Math.max(55,Math.min(1200,state.x));if(state.cloak){state.energy=Math.max(0,state.energy-14*dt);state.stats.cloakSeconds+=dt}else state.energy=Math.min(100,state.energy+10*dt);if(state.energy<=0)state.cloak=false;if(state.escapeActive&&state.escapeRemaining!=null){state.escapeRemaining-=dt;if(state.escapeRemaining<=0&&state.chapterIndex===15){state.escapeRemaining=0;cinematic('ÉCHEC DE LA FUITE','Le souffle de l’explosion rattrape Scar et Lex. Le checkpoint est restauré.',['CHECKPOINT'],()=>{state.escapeRemaining=88;loadBeat(state.beatIndex,true)})}}if(state.messageTime>0){state.messageTime-=dt;if(state.messageTime<=0)ui.status.textContent=''}updateAI(dt);updateAlly(dt);handleMode(dt);for(const s of state.shots){s.x+=s.vx;s.life--}state.shots=state.shots.filter(s=>s.life>0&&s.x<1300);for(const p of state.particles){p.x+=p.vx;p.y+=p.vy;p.vy+=.12;p.life--}state.particles=state.particles.filter(p=>p.life>0);state.cameraShake=Math.max(0,state.cameraShake-12*dt);ui.hp.style.width=state.hp+'%';ui.energy.style.width=state.energy+'%';ui.honor.style.width=state.honor+'%';const rem=CAMPAIGN.rules.pyramidFilmCycleSeconds-((t-state.filmEpoch)/1000%CAMPAIGN.rules.pyramidFilmCycleSeconds);ui.clock.textContent=fmt(rem);ui.escapeClock.textContent=state.escapeActive&&state.escapeRemaining!=null?'FUITE '+fmt(state.escapeRemaining):'';updateStats()}
function drawBackground(env,t){ctx.clearRect(0,0,1280,720);ctx.save();if(state.cameraShake)ctx.translate((Math.random()-.5)*state.cameraShake,(Math.random()-.5)*state.cameraShake*.45);const pal={ship:['#020705','#0c2016'],ice:['#0a2028','#163d48'],station:['#091116','#17272b'],ice_tunnel:['#081b21','#17414b'],pyramid:['#100f09','#2a2615'],pyramid_shift:['#120f08','#312813'],hive:['#030503','#121b12'],ice_night:['#06141a','#102c34']}[env]||['#050805','#141b15'];const g=ctx.createLinearGradient(0,0,0,720);g.addColorStop(0,pal[1]);g.addColorStop(1,pal[0]);ctx.fillStyle=g;ctx.fillRect(-20,-20,1320,760);const par=(state.x-640)*.08;if(env==='ship'){ctx.strokeStyle='#315841';ctx.lineWidth=8;for(let i=0;i<6;i++){ctx.beginPath();ctx.arc(180+i*230-par,350,180,Math.PI,Math.PI*2);ctx.stroke()}ctx.fillStyle='#173525';for(let i=0;i<12;i++)ctx.fillRect((i*130-par)%1400,170,34,8)}else if(env.includes('ice')){ctx.fillStyle='#315d68';ctx.globalAlpha=.55;ctx.beginPath();ctx.moveTo(0,500);for(let x=0;x<=1280;x+=120)ctx.lineTo(x,420+Math.sin(x*.017+t*.0003)*55);ctx.lineTo(1280,720);ctx.lineTo(0,720);ctx.fill();ctx.globalAlpha=.18;ctx.fillStyle='#bce8ef';for(let i=0;i<80;i++)ctx.fillRect((i*83+t*.06)%1320,70+(i*47)%500,2,14);ctx.globalAlpha=1}else if(env==='station'){ctx.fillStyle='#13282c';for(let i=0;i<8;i++)ctx.fillRect(i*190-par,280-(i%2)*60,150,300);ctx.strokeStyle='#567278';ctx.lineWidth=6;for(let i=0;i<8;i++){ctx.beginPath();ctx.moveTo(i*190-par,280);ctx.lineTo(i*190+120-par,190);ctx.stroke()}}else if(env==='hive'){ctx.fillStyle='#172217';for(let i=0;i<12;i++){ctx.beginPath();ctx.arc(i*130-par,560-(i%3)*70,90,Math.PI,Math.PI*2);ctx.fill()}ctx.strokeStyle='#4f6953';ctx.lineWidth=5;for(let i=0;i<18;i++){ctx.beginPath();ctx.moveTo(i*80-par,170);ctx.quadraticCurveTo(i*80+60-par,330,i*80+10-par,620);ctx.stroke()}}else{ctx.strokeStyle=env==='pyramid_shift'?'#8b7342':'#625d37';ctx.lineWidth=7;ctx.globalAlpha=.65;for(let i=0;i<9;i++){const x=i*175-par;ctx.beginPath();ctx.moveTo(x,585);ctx.lineTo(x+70,250);ctx.lineTo(x+140,585);ctx.stroke()}ctx.globalAlpha=1;if(env==='pyramid_shift'){const shift=(Math.sin(t*.001)*.5+.5)*90;ctx.fillStyle='#2a2412';ctx.fillRect(770+shift,180,95,410);ctx.fillRect(360-shift*.4,250,80,340)}}drawRoomProps(t,par);ctx.fillStyle='#09100b';ctx.fillRect(0,660,1280,60);ctx.strokeStyle='#365846';ctx.beginPath();ctx.moveTo(0,660);ctx.lineTo(1280,660);ctx.stroke();for(let i=1;i<3;i++){ctx.strokeStyle='#1d352a';ctx.setLineDash([8,12]);ctx.beginPath();ctx.moveTo(0,laneY[i]-8);ctx.lineTo(1280,laneY[i]-8);ctx.stroke();ctx.setLineDash([])}ctx.restore()}
function drawRoomProps(t,par){const r=room();if(r.id==='weapons_chamber'){for(let i=0;i<3;i++){ctx.fillStyle='#20281a';ctx.fillRect(350+i*220-par*.2,370,120,160);ctx.strokeStyle='#6a7942';ctx.strokeRect(350+i*220-par*.2,370,120,160);ctx.fillStyle='#9dc177';ctx.fillRect(396+i*220-par*.2,405,28,6)}}if(r.tags?.includes('grid')||r.id.startsWith('net_chamber')){ctx.fillStyle='#2b2516';ctx.fillRect(830-par*.15,280,70,300);ctx.fillStyle='#15110b';ctx.fillRect(845-par*.15,340,40,240)}if(r.tags?.includes('water_tank')){ctx.fillStyle='#283b40';ctx.fillRect(850,235,185,300);ctx.strokeStyle='#8ca6a3';ctx.lineWidth=6;ctx.strokeRect(850,235,185,300);ctx.beginPath();ctx.arc(942,235,92,Math.PI,Math.PI*2);ctx.stroke();ctx.strokeStyle='#68766e';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(1040,270);ctx.quadraticCurveTo(920,390,800,560);ctx.stroke()}if(r.env==='hive'||r.id==='egg_chamber'){ctx.fillStyle='#49523f';for(let i=0;i<7;i++){ctx.beginPath();ctx.ellipse(220+i*145-par*.05,610,25,42,0,0,Math.PI*2);ctx.fill()}}if(r.id==='mothership_mortuary'){ctx.fillStyle='#1d2c23';ctx.fillRect(410,420,470,80);ctx.strokeStyle='#758677';ctx.strokeRect(410,420,470,80)}if(r.id==='blooding_niche'){ctx.strokeStyle='#8dbf63';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(900,320);ctx.lineTo(955,390);ctx.lineTo(895,450);ctx.stroke()}if(r.id==='wrist_hologram'){ctx.strokeStyle='#85d5a0';ctx.globalAlpha=.45;ctx.beginPath();ctx.moveTo(570,500);ctx.lineTo(640,340);ctx.lineTo(710,500);ctx.closePath();ctx.stroke();ctx.globalAlpha=1}if(r.id==='stafford_pillar'){ctx.fillStyle='#24251c';ctx.fillRect(820,280,70,320);ctx.strokeStyle='#9aab9f';for(let i=0;i<7;i++){ctx.beginPath();ctx.moveTo(780,315+i*35);ctx.lineTo(930,420+i*15);ctx.stroke()}}if(r.id==='weyland_flame'){ctx.fillStyle='#b35a28';ctx.globalAlpha=.45;ctx.beginPath();ctx.moveTo(700,500);ctx.lineTo(930,390);ctx.lineTo(760,545);ctx.fill();ctx.globalAlpha=1}}
function drawPredator(){const x=state.x,y=laneY[state.lane];ctx.save();ctx.globalAlpha=state.cloak?.24:1;if(state.cloak)ctx.translate(Math.sin(performance.now()/30)*2,0);const accent=state.actor==='Celtic'?'#7d7259':state.actor==='Chopper'?'#697670':state.actor==='Elder'?'#a08255':'#88927d';ctx.fillStyle='#3e5542';ctx.strokeStyle='#172018';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(x,y-76,23,31,0,0,Math.PI*2);ctx.fill();ctx.stroke();if(state.actor==='Scar'&&!state.maskOn){ctx.fillStyle='#6b7654';ctx.beginPath();ctx.ellipse(x,y-86,19,18,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#29351f';ctx.beginPath();ctx.moveTo(x-9,y-79);ctx.lineTo(x-22,y-68);ctx.moveTo(x+9,y-79);ctx.lineTo(x+22,y-68);ctx.stroke()}else{ctx.fillStyle=accent;ctx.fillRect(x-17,y-94,34,25);ctx.strokeRect(x-17,y-94,34,25);}ctx.strokeStyle='#27352c';ctx.lineWidth=5;for(let i=0;i<6;i++){ctx.beginPath();ctx.moveTo(x-18+i*7,y-67);ctx.quadraticCurveTo(x-34+i*9,y-40,x-30+i*8,y-8);ctx.stroke()}ctx.fillStyle='#435a47';ctx.fillRect(x-20,y-42,40,57);ctx.fillStyle='#314238';ctx.fillRect(x-28,y-39,16,45);ctx.fillRect(x+12,y-39,16,45);ctx.strokeStyle='#778879';ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(x-16,y+10);ctx.lineTo(x-22,y+62);ctx.moveTo(x+16,y+10);ctx.lineTo(x+22,y+62);ctx.stroke();ctx.strokeStyle='#b6c6b7';ctx.lineWidth=4;if(state.weapon==='long_wrist_blades'||state.weapon==='wrist_blades'){ctx.beginPath();ctx.moveTo(x+26,y-15);ctx.lineTo(x+(state.weapon==='long_wrist_blades'?88:65),y-28);ctx.moveTo(x+26,y-9);ctx.lineTo(x+(state.weapon==='long_wrist_blades'?88:65),y-6);ctx.stroke()}if(state.weapon==='combistick'||state.weapon==='elder_spear'){ctx.beginPath();ctx.moveTo(x-58,y+18);ctx.lineTo(x+70,y-46);ctx.stroke()}if(state.plasma&&state.actor==='Scar'){ctx.fillStyle='#6a7d70';ctx.fillRect(x+18,y-74,20,13);ctx.strokeStyle='#b3d5b7';ctx.beginPath();ctx.moveTo(x+35,y-72);ctx.lineTo(x+54,y-83);ctx.stroke()}if(state.blooded&&state.actor==='Scar'){ctx.strokeStyle='#aaff62';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x-7,y-87);ctx.lineTo(x+8,y-76);ctx.moveTo(x-9,y-80);ctx.lineTo(x+7,y-69);ctx.stroke()}if(state.vision){ctx.strokeStyle=state.vision===1?'#ff8b63':'#8dff7e';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y-80,38,0,Math.PI*2);ctx.stroke()}ctx.restore()}

function drawAlly(){if(!state.allyActive)return;const x=state.allyX,y=laneY[state.allyLane];ctx.save();ctx.fillStyle='#6e8082';ctx.strokeStyle='#1a2525';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y-56,9,0,Math.PI*2);ctx.fill();ctx.fillRect(x-9,y-45,18,38);ctx.strokeStyle='#8fa5a0';ctx.beginPath();ctx.moveTo(x-5,y-8);ctx.lineTo(x-12,y+38);ctx.moveTo(x+5,y-8);ctx.lineTo(x+12,y+38);ctx.stroke();if(state.lexGear){ctx.strokeStyle='#b8c8b8';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x+10,y-30);ctx.lineTo(x+58,y-65);ctx.stroke();ctx.fillStyle='#3f5b48';ctx.beginPath();ctx.ellipse(x-18,y-27,17,23,-.2,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#c9ddd5';ctx.font='10px system-ui';ctx.fillText('LEX',x-12,y-84);ctx.restore()}

function drawEnemy(e){if(e.dead)return;const x=e.x,y=laneY[e.lane];ctx.save();const human=['human_security','weyland','weyland_hostile','quinn','quinn_injured','stafford','stafford_trapped'].includes(e.type),xeno=!human;if(state.vision===1){ctx.globalAlpha=human?1:.4;ctx.shadowBlur=human?18:0;ctx.shadowColor='#ff7b4a'}if(state.vision===2){ctx.globalAlpha=xeno?1:.3;ctx.shadowBlur=xeno?20:0;ctx.shadowColor='#71ff72'}if(human){ctx.fillStyle=e.type.includes('weyland')?'#8d907c':e.type.includes('quinn')?'#7f8b8f':e.type.includes('stafford')?'#788d91':'#85979b';ctx.beginPath();ctx.arc(x,y-55,10,0,Math.PI*2);ctx.fill();ctx.fillRect(x-10,y-44,20,42);ctx.strokeStyle=e.hostile?'#d5a063':'#7c9384';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x+7,y-31);ctx.lineTo(x+30,y-18);ctx.stroke()}else{ctx.fillStyle=e.type==='queen'?'#1d271e':'#182018';ctx.strokeStyle=e.type==='grid'?'#9ed65e':'#5d7763';ctx.lineWidth=e.type==='queen'?7:4;const scale=e.type==='queen'?1.55:e.type==='facehugger'?.55:1;ctx.beginPath();ctx.ellipse(x,y-70*scale,42*scale,22*scale,-.2,Math.PI,Math.PI*2);ctx.stroke();ctx.fillRect(x-12*scale,y-65*scale,24*scale,58*scale);ctx.beginPath();ctx.moveTo(x-10,y-34);ctx.lineTo(x-48*scale,y+18);ctx.moveTo(x+10,y-34);ctx.lineTo(x+48*scale,y+18);ctx.stroke();if(e.type!=='facehugger'){ctx.beginPath();ctx.moveTo(x+30*scale,y-52*scale);ctx.quadraticCurveTo(x+95*scale,y-32*scale,x+72*scale,y+30);ctx.stroke()}if(e.type==='grid'){ctx.strokeStyle='#aaff5f';ctx.beginPath();ctx.moveTo(x-25,y-86);ctx.lineTo(x+25,y-55);ctx.moveTo(x-28,y-70);ctx.lineTo(x+20,y-43);ctx.stroke()}}ctx.shadowBlur=0;if(e.entangled>0){ctx.strokeStyle='#b7c4ba';ctx.lineWidth=2;for(let i=-35;i<=35;i+=10){ctx.beginPath();ctx.moveTo(x-40,y-105+i);ctx.lineTo(x+40,y-25+i);ctx.stroke()}}if(e.boss){ctx.fillStyle='#130909';ctx.fillRect(x-60,y-156,120,7);ctx.fillStyle='#b0d97b';ctx.fillRect(x-60,y-156,120*(e.hp/e.maxHp),7)}ctx.restore()}
function drawObjectiveMarker(){if(state.objectiveDone)return;const b=beat();if(['combat_human','combat_xeno','combat_plasma','boss_grid','boss_queen','survive'].includes(b.mode))return;const x=1040,y=laneY[Math.min(state.lane,(room().lanes||3)-1)]-100;ctx.save();ctx.strokeStyle='#b6e886';ctx.lineWidth=2;ctx.setLineDash([6,6]);ctx.beginPath();ctx.arc(x,y,22,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#b6e886';ctx.font='12px system-ui';ctx.fillText(b.mode.includes('reach')||b.mode.includes('escape')||b.mode.startsWith('scripted_')?'SORTIE':'INTERAGIR',x-27,y-30);ctx.restore()}
function drawSecondaryMarker(){const s=currentSecondary();if(!s)return;ctx.save();const y=laneY[s.lane]-115;ctx.strokeStyle='#e2b968';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(s.x-10,y);ctx.lineTo(s.x,y-10);ctx.lineTo(s.x+10,y);ctx.lineTo(s.x,y+10);ctx.closePath();ctx.stroke();ctx.fillStyle='#e2b968';ctx.font='10px system-ui';ctx.fillText('TRACE',s.x-16,y-18);ctx.restore()}
function drawShots(){for(const s of state.shots){ctx.fillStyle=s.type==='plasmacaster'?'#9dff85':s.type==='shuriken'?'#d7e1d8':s.type==='wrist_blade_projectile'?'#e8efe9':'#bfc7c1';ctx.beginPath();ctx.arc(s.x,s.y,s.type==='net'?6:4,0,Math.PI*2);ctx.fill()}}
function drawParticles(){for(const p of state.particles){ctx.globalAlpha=Math.max(0,p.life/50);ctx.fillStyle=p.type==='acid'?'#afff55':'#dbb072';ctx.fillRect(p.x,p.y,3,3)}ctx.globalAlpha=1}
function drawVision(){if(!state.vision)return;ctx.save();ctx.globalAlpha=.09;ctx.fillStyle=state.vision===1?'#ff4d26':'#35ff67';ctx.fillRect(0,0,1280,720);ctx.globalAlpha=.16;ctx.strokeStyle=state.vision===1?'#ffb18e':'#a4ffb5';for(let y=0;y<720;y+=8){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1280,y);ctx.stroke()}ctx.restore()}
function render(t){drawBackground(room().env,t);drawObjectiveMarker();drawSecondaryMarker();for(const e of state.enemies)drawEnemy(e);drawAlly();drawPredator();drawShots();drawParticles();drawVision();ctx.fillStyle='#a8bbb0';ctx.font='13px ui-monospace,monospace';ctx.fillText(room().name.toUpperCase(),22,695);if(state.message){ctx.fillStyle='#e1bd70';ctx.fillText(state.message.toUpperCase(),22,42)}}
function loop(t){const dt=Math.min(.033,(t-state.last)/1000||0);state.last=t;update(dt,t);render(t);requestAnimationFrame(loop)}
let audioCtx=null;function sfx(kind){if(!state.sound)return;const A=window.AudioContext||window.webkitAudioContext;if(!A)return;try{audioCtx=audioCtx||new A();const o=audioCtx.createOscillator(),g=audioCtx.createGain(),map={select:320,scan:880,objective:540,blade:160,shot:660,acid:220,hit:180,hurt:90,error:120,alert:440,dash:260};o.frequency.value=map[kind]||240;o.type=kind==='scan'?'sine':'triangle';g.gain.value=.035;o.connect(g);g.connect(audioCtx.destination);const n=audioCtx.currentTime;g.gain.setValueAtTime(.035,n);g.gain.exponentialRampToValueAtTime(.001,n+.08);o.start(n);o.stop(n+.09)}catch(e){}}
function wristComputer(){state.wristOpen=!state.wristOpen;if(ui.wrist){ui.wrist.classList.toggle('show',state.wristOpen);const b=beat(),r=room(),targets=state.enemies.filter(e=>!e.dead).map(e=>(e.hostile?'VALID':'HOLD')+' '+e.label).join(' · ')||'AUCUNE SIGNATURE';ui.wristText.textContent=`${state.actor} // ${r.name} // PLAN ${state.lane+1}/${r.lanes} // ${targets} // OBJECTIF: ${b.objective}`;}status(state.wristOpen?'WRIST COMPUTER DÉPLOYÉ':'WRIST COMPUTER FERMÉ');}
function keyAction(code,down){if(code==='ArrowLeft'||code==='KeyA')keys.left=down;if(code==='ArrowRight'||code==='KeyD')keys.right=down;if(!down)return;if(code==='KeyQ'){state.lane=(state.lane+1)%(room().lanes||3);status('PLAN DE PROFONDEUR '+(state.lane+1)+'/'+(room().lanes||3))}if(code==='KeyC'){if(state.energy>10)state.cloak=!state.cloak;status(state.cloak?'CAMOUFLAGE ACTIF':'CAMOUFLAGE COUPÉ')}if(code==='KeyV'){state.vision=(state.vision+1)%3;status(['VISION NORMALE','VISION THERMIQUE','VISION XÉNOMORPHE'][state.vision])}if(code==='KeyX')cycleWeapon();if(code==='KeyF')attack();if(code==='KeyR')quickRanged();if(code==='KeyE')interact();if(code==='Space')dodge();if(code==='KeyB')wristComputer();if(code==='Tab')ui.codex.classList.toggle('show');if(code==='Escape')ui.side.classList.toggle('open');updateHUD()}
addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','KeyA','KeyD','KeyQ','KeyC','KeyV','KeyX','KeyF','KeyR','KeyE','KeyB','Tab','Space','Escape'].includes(e.code))e.preventDefault();keyAction(e.code,true)});addEventListener('keyup',e=>keyAction(e.code,false));
document.querySelectorAll('[data-k]').forEach(b=>{const a=b.dataset.k;const down=()=>{if(a==='left'||a==='right')keys[a]=true;else if(a==='depth')keyAction('KeyQ',true);else if(a==='cloak')keyAction('KeyC',true);else if(a==='vision')keyAction('KeyV',true);else if(a==='weapon')keyAction('KeyX',true);else if(a==='attack')keyAction('KeyF',true);else if(a==='range')keyAction('KeyR',true);else if(a==='use')keyAction('KeyE',true);else if(a==='wrist')keyAction('KeyB',true);else if(a==='dodge')keyAction('Space',true)};const up=()=>{if(a==='left'||a==='right')keys[a]=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up)});
$('restart').onclick=()=>newHunt(true);$('codex-open').onclick=()=>ui.codex.classList.add('show');$('codex-close').onclick=()=>ui.codex.classList.remove('show');$('fullscreen').onclick=()=>document.documentElement.requestFullscreen?.();$('menu-toggle').onclick=()=>ui.side.classList.toggle('open');$('profile-load').onclick=()=>loadProfile($('profile-select').value);$('menu-profile').onchange=()=>state.profile=Number($('menu-profile').value);$('menu-continue').onclick=()=>{state.difficulty=$('menu-difficulty').value;loadProfile($('menu-profile').value);ui.menu.classList.remove('show')};$('menu-new').onclick=()=>{state.profile=Number($('menu-profile').value);state.difficulty=$('menu-difficulty').value;newHunt(true)};$('menu-codex').onclick=()=>ui.codex.classList.add('show');ui.difficulty.onchange=()=>{state.difficulty=ui.difficulty.value;save(true);updateHUD()};ui.menuDifficulty.onchange=()=>state.difficulty=ui.menuDifficulty.value;ui.sound.onclick=()=>{state.sound=!state.sound;save(true);syncProfiles()};
ui.meta.textContent=`v${CAMPAIGN.version} · ${CAMPAIGN.chapterCount} chapitres · ${CAMPAIGN.beatCount} séquences · ${ROOMS.length} pièces · ${SECONDARY.length} traces`;$('qa-badge').classList.toggle('show',QA);loadProfile(1,true);if(QA&&QUERY.has('chapter')){const ci=Number(QUERY.get('chapter'))||0,bi=Number(QUERY.get('beat'))||0;state.unlockedChapter=CAMPAIGN.chapters.length-1;loadChapter(ci,bi,true)}if(AUTOSTART)ui.menu.classList.remove('show');document.body.dataset.runtimeReady='1';canvas.focus();requestAnimationFrame(loop);
window.__AVP_TEST__={version:CAMPAIGN.version,campaign:CAMPAIGN,rooms:ROOMS,weapons:WEAPONS,secondary:SECONDARY,get state(){return {profile:state.profile,difficulty:state.difficulty,chapterIndex:state.chapterIndex,beatIndex:state.beatIndex,chapter:chapter().id,beat:beat().id,actor:state.actor,room:state.roomId,hp:state.hp,energy:state.energy,honor:state.honor,armor:state.armor,maskOn:state.maskOn,allyActive:state.allyActive,weapon:state.weapon,plasma:state.plasma,blooded:state.blooded,infectedHidden:state.infectedHidden,unlockedChapter:state.unlockedChapter,traces:[...state.traces],disabledWeapons:{...state.disabledWeapons},weaponAmmo:{...state.weaponAmmo},enemies:state.enemies.map(e=>({type:e.type,hp:e.hp,dead:e.dead,hostile:e.hostile,lane:e.lane})),flags:{...state.flags},stats:{...state.stats}}},gotoChapter(i,b=0){loadChapter(i,b,true)},gotoBeat(b){loadBeat(b,true)},setX(x){state.x=x},setWeapon(w){if(WEAPONS[w])state.weapon=w},setLane(l){state.lane=l},interact,attack,quickRanged,dodge,wristComputer,huntGrade,complete(){completeObjective('test')},advanceCinema(){ui.cineNext.onclick?.()},newHunt(){newHunt(false)},step(dt=.2){update(dt,performance.now())},render(){render(performance.now())},scan(id){const s=SECONDARY.find(x=>x.id===id);if(s)scanSecondary(s)}};
